{"path":"assets/css/styles.css","content":"/* Dental Premium Template Styles */
:root {
  --brand-600: #1292a6;
  --brand-700: #0f7b8b;
  --brand-800: #0c6674;
  --accent-500: #f59e0b;
  --bg: #f7fafc;
  --surface: #ffffff;
  --text: #0f172a;
  --muted: #334155;
  --border: #e2e8f0;
  --success: #16a34a;
  --danger: #dc2626;
  --radius: 14px;
  --shadow-sm: 0 1px 2px rgba(2, 8, 23, 0.06);
  --shadow: 0 8px 24px rgba(2, 8, 23, 0.08);
  --shadow-lg: 0 16px 48px rgba(2, 8, 23, 0.12);
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, "Helvetica Neue", Arial, "Noto Sans", "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji", sans-serif;
  background: linear-gradient(180deg, #ffffff 0%, var(--bg) 100%);
  line-height: 1.55;
}
img { max-width: 100%; display: block; }
svg { display: block; }

.container { width: min(1200px, 100% - 2rem); margin: 0 auto; }
.section { padding: clamp(2.5rem, 6vw, 5rem) 0; }
.section-sm { padding: 2rem 0; }

h1, h2, h3 { line-height: 1.2; margin: 0 0 0.75rem; }
h1 { font-size: clamp(2rem, 4vw, 3rem); letter-spacing: -0.02em; }
h2 { font-size: clamp(1.5rem, 3vw, 2rem); letter-spacing: -0.01em; }
h3 { font-size: clamp(1.125rem, 2.5vw, 1.375rem); }
p { margin: 0 0 1rem; color: var(--muted); }

.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }

/* Header */
.topbar {
  background: var(--brand-800);
  color: #e6fdff;
  font-size: 0.9rem;
}
.topbar .bar-inner { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 0.5rem 0; }
.topbar a { color: #e6fdff; text-decoration: none; }
.topbar a:hover { text-decoration: underline; }

.header {
  position: sticky; top: 0; z-index: 40;
  background: rgba(255,255,255,0.8);
  backdrop-filter: saturate(180%) blur(10px);
  border-bottom: 1px solid var(--border);
}
.nav {
  display: flex; align-items: center; justify-content: space-between; gap: 1rem;
  padding: 0.75rem 0;
}
.brand { display: flex; align-items: center; gap: 0.75rem; text-decoration: none; color: var(--text); }
.brand-mark { width: 40px; height: 40px; border-radius: 50%; background: radial-gradient(90% 90% at 30% 30%, #e8fbff 0%, #b8f2ff 55%, #8be6f4 100%); border: 2px solid #cfeef5; box-shadow: var(--shadow-sm); }
.brand h1 { font-size: 1.125rem; margin: 0; }
.tagline { color: var(--muted); font-size: 0.9rem; }

.nav-links { display: flex; align-items: center; gap: 1rem; }
.nav-links a { text-decoration: none; color: var(--muted); padding: 0.5rem 0.75rem; border-radius: 999px; }
.nav-links a[aria-current="page"], .nav-links a:hover { color: var(--text); background: #f1f5f9; }

.nav-cta { display: flex; align-items: center; gap: 0.5rem; }

#navToggle { display: none; }

/* Buttons */
.btn { --btn-bg: #e2e8f0; --btn-color: #0f172a; display: inline-flex; align-items: center; justify-content: center; gap: 0.5rem; padding: 0.7rem 1rem; border-radius: 999px; border: 1px solid transparent; background: var(--btn-bg); color: var(--btn-color); text-decoration: none; font-weight: 600; box-shadow: var(--shadow-sm); transition: transform 120ms ease, box-shadow 120ms ease, background 120ms ease; }
.btn:hover { transform: translateY(-1px); box-shadow: var(--shadow); }
.btn:active { transform: translateY(0); box-shadow: var(--shadow-sm); }
.btn-primary { --btn-bg: linear-gradient(135deg, var(--brand-700), var(--brand-600)); --btn-color: #ffffff; }
.btn-outline { background: transparent; border-color: #cbd5e1; }
.btn-accent { --btn-bg: var(--accent-500); --btn-color: #111827; }
.btn-block { width: 100%; }
.btn-sm { padding: 0.5rem 0.75rem; font-size: 0.9rem; }

.badge { display: inline-flex; align-items: center; gap: 0.35rem; background: #ecfeff; color: var(--brand-800); padding: 0.25rem 0.6rem; border-radius: 999px; border: 1px solid #cffafe; font-weight: 600; font-size: 0.8rem; }

/* Hero */
.hero { position: relative; overflow: hidden; background: radial-gradient(1200px 500px at 80% -20%, #c1f4ff 0%, transparent 60%) no-repeat, #ffffff; }
.hero::after { content: ""; position: absolute; inset: -10% -20% auto auto; width: 70%; height: 100%; background: url('../img/hero-abstract.svg') right top / contain no-repeat; opacity: 0.35; pointer-events: none; }
.hero .grid { display: grid; grid-template-columns: 1.1fr 0.9fr; gap: clamp(1rem, 4vw, 2rem); align-items: center; }
.hero-card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); box-shadow: var(--shadow-lg); padding: clamp(1rem, 3vw, 2rem); position: relative; }
.hero-list { display: grid; gap: 0.5rem; margin: 1rem 0; }
.hero-usp { display: flex; align-items: center; gap: 0.5rem; }
.hero-usp svg { color: var(--success); }

/* Grids */
.grid-3 { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.25rem; }
.grid-2 { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1.25rem; }
.grid-auto { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 1.25rem; }

.card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); box-shadow: var(--shadow); padding: 1.25rem; }
.card h3 { margin-bottom: 0.5rem; }
.card-muted { background: #f8fafc; border-style: dashed; }

/* Lists & pills */
.pills { display: flex; flex-wrap: wrap; gap: 0.5rem; }
.pill { background: #eff6ff; color: #1e3a8a; border: 1px solid #dbeafe; padding: 0.4rem 0.6rem; border-radius: 999px; font-weight: 600; font-size: 0.9rem; }

/* Review stars */
.stars { --size: 18px; display: inline-grid; grid-auto-flow: column; gap: 2px; }
.star { width: var(--size); height: var(--size); color: #fbbf24; }

/* Media object */
.media { display: grid; grid-template-columns: auto 1fr; gap: 0.75rem; align-items: center; }
.avatar { width: 56px; height: 56px; border-radius: 50%; overflow: hidden; border: 1px solid var(--border); background: #e2f8fb; }

/* Forms */
.form { display: grid; gap: 1rem; }
.input, select, textarea { width: 100%; padding: 0.75rem; border-radius: 12px; border: 1px solid #cbd5e1; background: #ffffff; font: inherit; color: var(--text); }
textarea { min-height: 120px; resize: vertical; }
.label { font-weight: 600; color: var(--muted); display: block; margin-bottom: 0.35rem; }
.help { font-size: 0.9rem; color: #64748b; }
.field-inline { display: grid; grid-template-columns: 1fr 1fr; gap: 0.75rem; }
.status { padding: 0.75rem; border-radius: 12px; border: 1px solid; }
.status.success { color: #065f46; background: #ecfdf5; border-color: #a7f3d0; }
.status.error { color: #7f1d1d; background: #fef2f2; border-color: #fecaca; }

/* Table-like hours */
.hours { width: 100%; border-collapse: collapse; }
.hours th, .hours td { padding: 0.6rem 0.4rem; border-bottom: 1px dashed #e2e8f0; text-align: left; }
.hours th { color: var(--muted); font-weight: 600; }

/* Footer */
.footer { background: #061e24; color: #d1f6ff; }
.footer a { color: #a6f0ff; text-decoration: none; }
.footer a:hover { text-decoration: underline; }
.footer .cols { display: grid; grid-template-columns: 1.2fr 1fr 1fr; gap: 1.5rem; }
.footer .legal { border-top: 1px solid rgba(255,255,255,0.08); margin-top: 1.5rem; padding-top: 1rem; font-size: 0.9rem; color: #8bb8c0; }

/* Utilities */
.muted { color: var(--muted); }
.center { text-align: center; }
.stack { display: grid; gap: 0.75rem; }
.stack-lg { gap: 1.25rem; }
.mt-2 { margin-top: 0.5rem; }
.mt-4 { margin-top: 1rem; }
.mt-6 { margin-top: 1.5rem; }
.mt-8 { margin-top: 2rem; }
.mb-0 { margin-bottom: 0; }
.p-0 { padding: 0; }
.py-0 { padding-top: 0; padding-bottom: 0; }

.kicker { display: inline-flex; align-items: center; gap: 0.5rem; color: var(--brand-700); font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; font-size: 0.8rem; background: #ecfeff; border: 1px solid #cffafe; padding: 0.25rem 0.5rem; border-radius: 999px; }

/* Accordion */
.accordion { border: 1px solid var(--border); border-radius: 12px; overflow: hidden; background: #fff; }
.acc-item + .acc-item { border-top: 1px solid var(--border); }
.acc-btn { width: 100%; text-align: left; padding: 1rem; font-weight: 700; background: #fff; border: 0; display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 1rem; cursor: pointer; }
.acc-panel { display: grid; grid-template-rows: 0fr; transition: grid-template-rows 200ms ease; }
.acc-panel > div { overflow: hidden; }
.acc-item[open] .acc-panel { grid-template-rows: 1fr; }

/* Floating CTA (mobile) */
.floating-cta { position: fixed; bottom: 1rem; left: 0; right: 0; display: none; padding: 0 1rem; z-index: 30; }
.floating-cta .btn { width: 100%; box-shadow: var(--shadow-lg); }

/* Responsive */
@media (max-width: 960px) {
  .hero .grid { grid-template-columns: 1fr; }
  .grid-3 { grid-template-columns: 1fr 1fr; }
  .footer .cols { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 720px) {
  #navToggle { display: inline-flex; align-items: center; justify-content: center; width: 44px; height: 44px; border-radius: 12px; background: #f1f5f9; border: 1px solid #e2e8f0; }
  .nav-links { position: fixed; inset: 64px 0 auto 0; transform: translateY(-16px); opacity: 0; visibility: hidden; transition: opacity 160ms ease, transform 160ms ease; background: rgba(255,255,255,0.97); backdrop-filter: blur(8px); border-bottom: 1px solid var(--border); padding: 0.75rem; flex-direction: column; align-items: stretch; }
  .nav-links a { padding: 0.9rem 0.75rem; font-size: 1.05rem; }
  .nav.is-open .nav-links { transform: none; opacity: 1; visibility: visible; }
  .grid-3, .grid-2 { grid-template-columns: 1fr; }
  .field-inline { grid-template-columns: 1fr; }
  .floating-cta { display: block; }
}

/* Link styles */
a { color: var(--brand-700); }
a:hover { color: var(--brand-800); }

/* Table alt style */
.table { width: 100%; border-collapse: collapse; border: 1px solid var(--border); border-radius: 12px; overflow: hidden; }
.table th, .table td { padding: 0.75rem; border-bottom: 1px solid var(--border); text-align: left; }
.table thead th { background: #f1f5f9; font-weight: 700; color: var(--muted); }

/* Quote */
.quote { position: relative; padding-left: 1rem; border-left: 4px solid #c7f0f6; color: var(--muted); }

/* Utility icons */
.icon { width: 20px; height: 20px; display: inline-block; }

/* Highlight banner */
.banner { background: linear-gradient(90deg, #e0fbff, #fff8eb); border: 1px solid #d9f5fb; border-radius: 14px; padding: 0.75rem 1rem; }
"} 
{"path":"assets/js/main.js","content":"(function(){
  const $ = (s, c=document) => c.querySelector(s);
  const $$ = (s, c=document) => Array.from(c.querySelectorAll(s));

  // Mobile nav toggle
  const nav = $('.nav');
  const navToggle = $('#navToggle');
  if(nav && navToggle){
    navToggle.addEventListener('click', ()=>{
      const open = nav.classList.toggle('is-open');
      navToggle.setAttribute('aria-expanded', open? 'true' : 'false');
    });
  }

  // Current page highlighting
  const path = location.pathname.split('/').pop() || 'index.html';
  $$('.nav-links a').forEach(a=>{
    const href = a.getAttribute('href');
    if((path === '' && href === 'index.html') || href === path){
      a.setAttribute('aria-current','page');
    }
  });

  // Simple accordion
  $$('.acc-btn').forEach(btn=>{
    btn.addEventListener('click', ()=>{
      const item = btn.closest('.acc-item');
      const open = item.hasAttribute('open');
      item.toggleAttribute('open');
      btn.setAttribute('aria-expanded', open ? 'false' : 'true');
    });
  });

  // Form handling: validate and show inline success without network
  function handleForm(form){
    form.addEventListener('submit', (e)=>{
      e.preventDefault();
      const required = $$('[required]', form);
      let ok = true;
      required.forEach(f=>{
        if(!f.value){ ok = false; f.setAttribute('aria-invalid','true'); f.focus(); }
      });
      const status = form.querySelector('.js-status');
      if(ok){
        if(status){
          status.className = 'status success js-status';
          status.textContent = 'Thank you! Your request has been recorded. A team member will follow up shortly. For urgent needs, please call '+ (document.querySelector('[data-phone]')?.dataset.phone || '{{PHONE}}') +'.';
        }
        form.reset();
      } else {
        if(status){
          status.className = 'status error js-status';
          status.textContent = 'Please complete all required fields.';
        }
      }
    });
  }
  $$('form[data-form="request"]').forEach(handleForm);

  // Smooth anchor focus
  $$('a[href^="#"]').forEach(a=>{
    a.addEventListener('click', (e)=>{
      const id = a.getAttribute('href').slice(1);
      const el = document.getElementById(id);
      if(el){
        el.setAttribute('tabindex','-1');
        el.addEventListener('blur', ()=> el.removeAttribute('tabindex'), {once:true});
      }
    });
  });
})();
"} 
