{"path":"index.html","content":"<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{{BUSINESS_NAME}} | {{TAGLINE}} | Family & Cosmetic Dentistry in {{CITY}}, {{STATE}}</title>
  <meta name="description" content="{{BUSINESS_NAME}} offers gentle, modern dental care for families in {{CITY}}, {{STATE}}. Preventive, cosmetic, implants, and same-day emergencies. Call {{PHONE}}.">
  <link rel="canonical" href="/index.html">
  <meta name="theme-color" content="#0f7b8b">
  <meta name="robots" content="index,follow">
  <meta property="og:type" content="website">
  <meta property="og:site_name" content="{{BUSINESS_NAME}}">
  <meta property="og:title" content="{{BUSINESS_NAME}} — {{TAGLINE}}">
  <meta property="og:description" content="Gentle, modern dental care in {{CITY}}, {{STATE}}. New patient specials and same-day emergencies.">
  <meta property="og:url" content="/index.html">
  <meta property="og:image" content="/assets/img/hero-abstract.svg">
  <meta name="twitter:card" content="summary_large_image">
  <meta name="twitter:title" content="{{BUSINESS_NAME}} — {{TAGLINE}}">
  <meta name="twitter:description" content="Gentle, modern dental care in {{CITY}}, {{STATE}}.">
  <meta name="twitter:image" content="/assets/img/hero-abstract.svg">
  <script type="application/ld+json">
  {
    "@context": "https://schema.org",
    "@type": "Dentist",
    "name": "{{BUSINESS_NAME}}",
    "image": "/assets/img/hero-abstract.svg",
    "telephone": "{{PHONE}}",
    "email": "{{EMAIL}}",
    "address": {
      "@type": "PostalAddress",
      "streetAddress": "{{ADDRESS}}",
      "addressLocality": "{{CITY}}",
      "addressRegion": "{{STATE}}",
      "postalCode": "{{ZIP}}"
    },
    "openingHours": "{{HOURS}}",
    "url": "/index.html",
    "areaServed": "{{CITY}}, {{STATE}}"
  }
  </script>
  <link rel="stylesheet" href="/assets/css/styles.css">
</head>
<body>
  <a class="sr-only" href="#main">Skip to content</a>
  <div class="topbar">
    <div class="container bar-inner">
      <div class="stack">
        <div><strong>{{BUSINESS_NAME}}</strong> · <span class="tagline">{{TAGLINE}}</span></div>
      </div>
      <div class="stack" style="text-align:right">
        <div>Call <a data-phone data-cta="phone" href="tel:{{PHONE}}">{{PHONE}}</a></div>
        <div class="muted" aria-label="Office hours">Hours: {{HOURS}}</div>
      </div>
    </div>
  </div>
  <header class="header" role="banner">
    <div class="container nav">
      <a class="brand" href="/index.html" aria-label="{{BUSINESS_NAME}} home">
        <span class="brand-mark" aria-hidden="true"></span>
        <span>
          <h1 class="mb-0">{{BUSINESS_NAME}}</h1>
          <span class="tagline">{{TAGLINE}}</span>
        </span>
      </a>
      <nav class="nav-links" role="navigation" aria-label="Primary">
        <a href="/services.html">Services</a>
        <a href="/insurance.html">Insurance</a>
        <a href="/new-patient.html">New Patients</a>
        <a href="/about.html">About</a>
        <a href="/reviews.html">Reviews</a>
        <a href="/contact.html">Contact</a>
        <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </nav>
      <button id="navToggle" aria-expanded="false" aria-controls="primary-navigation" aria-label="Toggle navigation">
        <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#0f172a" stroke-width="2" stroke-linecap="round"><path d="M3 6h18M3 12h18M3 18h18"/></svg>
      </button>
    </div>
  </header>

  <main id="main">
    <section class="hero section">
      <div class="container">
        <div class="grid">
          <div class="hero-card">
            <span class="kicker">Compassionate Care • Advanced Technology</span>
            <h1>Healthy smiles start here in {{CITY}}, {{STATE}}</h1>
            <p>From routine cleanings to smile makeovers, {{BUSINESS_NAME}} delivers gentle, comprehensive dentistry for the whole family—on time, with comfort and transparency.</p>
            <div class="hero-list">
              <div class="hero-usp"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M20 6L9 17l-5-5"/></svg> Same-day emergency relief</div>
              <div class="hero-usp"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 13l4 4L19 7"/></svg> Transparent, upfront pricing</div>
              <div class="hero-usp"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/></svg> Early, late, and Saturday hours</div>
            </div>
            <div class="stack">
              <div class="pills">
                <span class="pill">Preventive</span>
                <span class="pill">Cosmetic</span>
                <span class="pill">Implants</span>
                <span class="pill">Invisalign</span>
                <span class="pill">Pediatric</span>
              </div>
              <div>
                <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
                <a class="btn btn-outline" href="/services.html">Explore services</a>
              </div>
              <div class="banner">
                New here? Ask about our New Patient Welcome: exam, X‑rays, and cleaning special. Limited time.
              </div>
            </div>
          </div>
          <div class="stack-lg">
            <div class="card">
              <h3>Trusted by neighbors in {{CITY}}</h3>
              <p class="quote">“The best dental experience I’ve ever had—thorough, painless, and so kind.”</p>
              <div class="media mt-4">
                <div class="avatar"><img src="/assets/img/avatar-01.svg" alt="Reviewer avatar"></div>
                <div>
                  <strong>Jordan P.</strong>
                  <div class="stars" aria-label="5 out of 5 stars">
                    <svg class="star" viewBox="0 0 24 24" fill="currentColor"><path d="M12 .587l3.668 7.431L24 9.748l-6 5.845L19.335 24 12 19.897 4.665 24 6 15.593 0 9.748l8.332-1.73z"/></svg>
                    <svg class="star" viewBox="0 0 24 24" fill="currentColor"><path d="M12 .587l3.668 7.431L24 9.748l-6 5.845L19.335 24 12 19.897 4.665 24 6 15.593 0 9.748l8.332-1.73z"/></svg>
                    <svg class="star" viewBox="0 0 24 24" fill="currentColor"><path d="M12 .587l3.668 7.431L24 9.748l-6 5.845L19.335 24 12 19.897 4.665 24 6 15.593 0 9.748l8.332-1.73z"/></svg>
                    <svg class="star" viewBox="0 0 24 24" fill="currentColor"><path d="M12 .587l3.668 7.431L24 9.748l-6 5.845L19.335 24 12 19.897 4.665 24 6 15.593 0 9.748l8.332-1.73z"/></svg>
