                <input class="input" id="np-email" name="email" type="email" required placeholder="you@example.com">
              </div>
            </div>
            <div>
              <label class="label" for="np-goal">Primary goal</label>
              <select id="np-goal" name="goal" class="input" required>
                <option value="" disabled selected>Select one</option>
                <option>Checkup & cleaning</option>
                <option>Dental pain or emergency</option>
                <option>Cosmetic consult</option>
                <option>Implant consult</option>
                <option>Other</option>
              </select>
            </div>
            <div>
              <label class="label" for="np-notes">Notes or concerns</label>
              <textarea id="np-notes" name="notes" placeholder="Tell us anything you'd like us to know"></textarea>
            </div>
            <p id="intakeHelp" class="help">Submitting this form shares your info with {{BUSINESS_NAME}}. We value your privacy and will only use it to coordinate care.</p>
