          <p>{{HOURS}}</p>
        </div>
        <div>
          <h3>Next steps</h3>
          <p class="stack">
            <a href="/book.html">Book online</a>
            <a href="/services.html">Explore services</a>
            <a href="/insurance.html">Verify insurance</a>
